  OBJECT_STATUS VARCHAR2(1) DEFAULT 'A' NOT NULL,
  CREATED_BY VARCHAR2(255) NOT NULL,
  CREATION_DATE DATE DEFAULT SYSDATE NOT NULL,
  LAST_UPDATED_BY VARCHAR2(255) NOT NULL,
  LAST_UPDATE_DATE DATE DEFAULT SYSDATE NOT NULL,
  OBJECT_VERSION_NUMBER NUMBER DEFAULT 1 NOT NULL,
  CONSTRAINT PK_HTH_REQUEST_API PRIMARY KEY (ID),
  CONSTRAINT UK_HTH_REQUEST_API UNIQUE (HTH_REQUEST_ID, API_MASTER_ID),
  CONSTRAINT FK_HTH_REQUEST_API_TO_REQUEST FOREIGN KEY (HTH_REQUEST_ID) REFERENCES HTH_BEA.HTH_MANAGEMENT_REQUEST(ID),
  CONSTRAINT FK_HTH_REQUEST_API_TO_API_MASTER FOREIGN KEY (API_MASTER_ID) REFERENCES HTH_BEA.HTH_API_MASTER(ID)
);

COMMENT ON TABLE HTH_BEA.HTH_MANAGEMENT_REQUEST_API IS 'HTH approval request API name snapshot.';

COMMENT ON COLUMN HTH_BEA.HTH_MANAGEMENT_REQUEST_API.HTH_REQUEST_ID IS 'References HTH_BEA.HTH_MANAGEMENT_REQUEST.ID.';

COMMENT ON COLUMN HTH_BEA.HTH_MANAGEMENT_REQUEST_API.API_MASTER_ID IS 'References HTH_BEA.HTH_API_MASTER.ID.';

COMMENT ON COLUMN HTH_BEA.HTH_MANAGEMENT_REQUEST_API.API_CODE IS 'Copied API code at submit time.';

COMMENT ON COLUMN HTH_BEA.HTH_MANAGEMENT_REQUEST_API.API_NAME IS 'Copied API name at submit time.';

CREATE TABLE HTH_BEA.HTH_CERTIFICATE (
