COMMENT ON COLUMN HTH_BEA.HTH_CERTIFICATE_REQUEST.SEQ_NO IS
  'Certificate sequence within one upload request.';

COMMENT ON COLUMN HTH_BEA.HTH_CERTIFICATE_REQUEST.FILE_NAME IS 'Uploaded PEM file name.';

COMMENT ON COLUMN HTH_BEA.HTH_CERTIFICATE_REQUEST.PEM_CONTENT IS 'Uploaded PEM public key content.';

CREATE TABLE HTH_BEA.HTH_USER_PROFILE (
  PARTY_ID VARCHAR2(64 BYTE) NOT NULL,
  CLOSE_ID VARCHAR2(255 BYTE) NOT NULL,
  API_PASSWORD_STATE VARCHAR2(16 BYTE) DEFAULT 'NOT_SETUP' NOT NULL,
  API_PASSWORD_CLIENT_ID VARCHAR2(64 BYTE),
  API_PASSWORD_REQUEST_ID VARCHAR2(36 BYTE),
  API_PASSWORD_UPDATED_AT TIMESTAMP,
  CONSTRAINT CK_HTH_USER_PWD_STATE CHECK (API_PASSWORD_STATE IN ('NOT_SETUP','ACTIVE','IN_PROGRESS','UNKNOWN')),
  CONSTRAINT PK_HTH_USER_PROFILE PRIMARY KEY (PARTY_ID, CLOSE_ID)
);

COMMENT ON TABLE HTH_BEA.HTH_USER_PROFILE IS
  'HTH user profile fields.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_PROFILE.PARTY_ID IS
  'Corporate party ID.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_PROFILE.CLOSE_ID IS
  'HTH CloseID associated with the corporate user.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_PROFILE.API_PASSWORD_STATE IS
  'CM-confirmed DSP password setup state; no password/hash is stored locally.';
COMMENT ON COLUMN HTH_BEA.HTH_USER_PROFILE.API_PASSWORD_CLIENT_ID IS
  'DSP business clientId binding for password state, not the APIC caller identity.';
COMMENT ON COLUMN HTH_BEA.HTH_USER_PROFILE.API_PASSWORD_REQUEST_ID IS
  'CM requestId binding for the current or latest password operation.';
COMMENT ON COLUMN HTH_BEA.HTH_USER_PROFILE.API_PASSWORD_UPDATED_AT IS
  'Last password-state update time; DSP remains the password store.';

CREATE TABLE HTH_BEA.HTH_USER_ACCESS_ACCOUNT (
  ID                    VARCHAR2(36 BYTE)  NOT NULL,
  PARTY_ID              VARCHAR2(64 BYTE)  NOT NULL,
  CLOSE_ID              VARCHAR2(255 BYTE) NOT NULL,
  ACCESS_PARTY_ID       VARCHAR2(64 BYTE)  NOT NULL,
  LINKAGE_TYPE          VARCHAR2(16 BYTE)  NOT NULL,
  ACCOUNT_NUMBER        VARCHAR2(64 BYTE)  NOT NULL,
  ACCOUNT_NUMBER_FORMATTED VARCHAR2(64 BYTE) NOT NULL,
  PRODUCT_CODE          VARCHAR2(32 BYTE),
  ACCOUNT_TYPE          VARCHAR2(8 BYTE)   NOT NULL,
  CURRENCY              VARCHAR2(3 BYTE),
  OBJECT_STATUS         VARCHAR2(1 BYTE)   DEFAULT 'A' NOT NULL,
  CREATED_BY            VARCHAR2(255 BYTE) NOT NULL,
  CREATION_DATE         DATE               DEFAULT SYSDATE NOT NULL,
  LAST_UPDATED_BY       VARCHAR2(255 BYTE) NOT NULL,
  LAST_UPDATE_DATE      DATE               DEFAULT SYSDATE NOT NULL,
  CONSTRAINT PK_HTH_UA_ACCOUNT PRIMARY KEY (ID),
  CONSTRAINT UK_HTH_UA_ACCOUNT UNIQUE
    (PARTY_ID, CLOSE_ID, ACCESS_PARTY_ID, LINKAGE_TYPE, ACCOUNT_TYPE, ACCOUNT_NUMBER),
  CONSTRAINT FK_HTH_UAA_USER_PROFILE FOREIGN KEY (PARTY_ID, CLOSE_ID)
    REFERENCES HTH_BEA.HTH_USER_PROFILE (PARTY_ID, CLOSE_ID),
  CONSTRAINT CK_HTH_UAA_LINKAGE CHECK
    (LINKAGE_TYPE IN ('RELATED', 'ASSOCIATED')),
  CONSTRAINT CK_HTH_UAA_TYPE CHECK (ACCOUNT_TYPE IN ('CSA', 'TD')),
  CONSTRAINT CK_HTH_UAA_STATUS CHECK (OBJECT_STATUS IN ('A', 'I'))
);

CREATE INDEX HTH_BEA.IX_HTH_UAA_ACCOUNT_NO
  ON HTH_BEA.HTH_USER_ACCESS_ACCOUNT (ACCOUNT_NUMBER);

CREATE INDEX HTH_BEA.IX_HTH_UAA_ACCOUNT_FMT
  ON HTH_BEA.HTH_USER_ACCESS_ACCOUNT (ACCOUNT_NUMBER_FORMATTED);

CREATE INDEX HTH_BEA.IX_HTH_UAA_CONTEXT
  ON HTH_BEA.HTH_USER_ACCESS_ACCOUNT
    (PARTY_ID, CLOSE_ID, ACCESS_PARTY_ID, LINKAGE_TYPE);

COMMENT ON TABLE HTH_BEA.HTH_USER_ACCESS_ACCOUNT IS
  'Effective Current and Savings or Time Deposit grants by HTH user and account-owning party.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.ID IS
  'Unique identifier of the effective account grant.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.PARTY_ID IS
  'Primary corporate party that owns the HTH user.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.CLOSE_ID IS
  'HTH user CloseID from HTH_USER_PROFILE.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.ACCESS_PARTY_ID IS
  'Party that owns the granted account.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.LINKAGE_TYPE IS
  'Company relationship type: RELATED or ASSOCIATED.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.ACCOUNT_NUMBER IS
  'Canonical/internal unmasked account identifier; must not be logged in plain text.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.ACCOUNT_NUMBER_FORMATTED IS
  'External/formatted account identifier from the BCO account catalogue; must not be logged in plain text.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.PRODUCT_CODE IS
  'BCO account product code; stored separately from the CSA/TD access account type.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.ACCOUNT_TYPE IS
  'Granted account type: CSA for Current and Savings or TD for Time Deposit.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.CURRENCY IS
  'Display snapshot only; not used to validate account ownership.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.OBJECT_STATUS IS
  'Record status: A for active or I for inactive.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.CREATED_BY IS
  'User who created the record.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.CREATION_DATE IS
  'Date and time when the record was created.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.LAST_UPDATED_BY IS
  'User who last updated the record.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT.LAST_UPDATE_DATE IS
  'Date and time when the record was last updated.';

CREATE TABLE HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API (
  ID                         VARCHAR2(36 BYTE)  NOT NULL,
  HTH_USER_ACCESS_ACCOUNT_ID VARCHAR2(36 BYTE)  NOT NULL,
  API_MASTER_ID              VARCHAR2(36 BYTE)  NOT NULL,
  OBJECT_STATUS              VARCHAR2(1 BYTE)   DEFAULT 'A' NOT NULL,
  CREATED_BY                 VARCHAR2(255 BYTE) NOT NULL,
  CREATION_DATE              DATE               DEFAULT SYSDATE NOT NULL,
  LAST_UPDATED_BY            VARCHAR2(255 BYTE) NOT NULL,
  LAST_UPDATE_DATE           DATE               DEFAULT SYSDATE NOT NULL,
  CONSTRAINT PK_HTH_UAA_API PRIMARY KEY (ID),
  CONSTRAINT UK_HTH_UAA_API UNIQUE
    (HTH_USER_ACCESS_ACCOUNT_ID, API_MASTER_ID),
  CONSTRAINT FK_HTH_UAAA_TO_ACCOUNT
    FOREIGN KEY (HTH_USER_ACCESS_ACCOUNT_ID)
    REFERENCES HTH_BEA.HTH_USER_ACCESS_ACCOUNT (ID),
  CONSTRAINT FK_HTH_UAAA_TO_API FOREIGN KEY (API_MASTER_ID)
    REFERENCES HTH_BEA.HTH_API_MASTER (ID),
  CONSTRAINT CK_HTH_UAAA_STATUS CHECK (OBJECT_STATUS IN ('A', 'I'))
);

CREATE INDEX HTH_BEA.IX_HTH_UAAA_API
  ON HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API (API_MASTER_ID);

COMMENT ON TABLE HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API IS
  'Effective HTH API grants by HTH user account.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API.ID IS
  'Unique identifier of the effective account API grant.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API.HTH_USER_ACCESS_ACCOUNT_ID IS
  'Effective HTH account grant owning this API grant.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API.API_MASTER_ID IS
  'References the active API definition in HTH_API_MASTER.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API.OBJECT_STATUS IS
  'Record status: A for active or I for inactive.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API.CREATED_BY IS
  'User who created the record.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API.CREATION_DATE IS
  'Date and time when the record was created.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API.LAST_UPDATED_BY IS
  'User who last updated the record.';

COMMENT ON COLUMN HTH_BEA.HTH_USER_ACCESS_ACCOUNT_API.LAST_UPDATE_DATE IS
  'Date and time when the record was last updated.';

CREATE TABLE HTH_BEA.HTH_API_PASSWORD_CODE (
  ID               VARCHAR2(36 BYTE)  NOT NULL,
  PARTY_ID         VARCHAR2(64 BYTE)  NOT NULL,
  USER_NAME        VARCHAR2(255 BYTE) NOT NULL,
  TRANSACTION_ID   VARCHAR2(64 BYTE),
  CODE_CIPHER      VARCHAR2(512 BYTE) NOT NULL,
  STATUS           VARCHAR2(16 BYTE)  DEFAULT 'PENDING' NOT NULL,
  ATTEMPT_COUNT    NUMBER(3)          DEFAULT 0 NOT NULL,
  EXPIRY_TIME      TIMESTAMP(6),
  USED_TIME        TIMESTAMP(6),
  OBJECT_STATUS    VARCHAR2(1 BYTE)   DEFAULT 'A' NOT NULL,
  CREATED_BY       VARCHAR2(255 BYTE) NOT NULL,
  CREATION_DATE    DATE               DEFAULT SYSDATE NOT NULL,
  LAST_UPDATED_BY  VARCHAR2(255 BYTE) NOT NULL,
  LAST_UPDATE_DATE DATE               DEFAULT SYSDATE NOT NULL,
  PURPOSE VARCHAR2(8 BYTE) DEFAULT 'SETUP' NOT NULL,
  REQUEST_ID VARCHAR2(36 BYTE),
  REMOTE_CLIENT_ID VARCHAR2(64 BYTE),
  MAX_ATTEMPTS NUMBER(3) DEFAULT 5 NOT NULL,
  CONSTRAINT CK_HTH_API_PWD_PURPOSE CHECK (PURPOSE IN ('SETUP','RESET')),
  CONSTRAINT CK_HTH_API_PWD_ATTEMPTS CHECK (ATTEMPT_COUNT >= 0 AND MAX_ATTEMPTS > 0 AND ATTEMPT_COUNT <= MAX_ATTEMPTS),
  CONSTRAINT PK_HTH_API_PASSWORD_CODE PRIMARY KEY (ID),
  CONSTRAINT CK_HTH_API_PWD_CODE_STATUS CHECK (STATUS IN
    ('PENDING', 'ACTIVE', 'USED', 'EXPIRED', 'INVALID', 'IN_PROGRESS', 'UNKNOWN'))
);

CREATE INDEX HTH_BEA.IX_HTH_API_PWD_CODE_TXN
   ON HTH_BEA.HTH_API_PASSWORD_CODE (TRANSACTION_ID);

CREATE INDEX HTH_BEA.IX_HTH_API_PWD_CODE_OWN
   ON HTH_BEA.HTH_API_PASSWORD_CODE (PARTY_ID, USER_NAME, STATUS);

CREATE UNIQUE INDEX HTH_BEA.UX_HTH_API_PWD_CODE_LIVE
    ON HTH_BEA.HTH_API_PASSWORD_CODE (
      CASE WHEN OBJECT_STATUS = 'A' AND STATUS IN ('ACTIVE','IN_PROGRESS','UNKNOWN') THEN PARTY_ID END,
      CASE WHEN OBJECT_STATUS = 'A' AND STATUS IN ('ACTIVE','IN_PROGRESS','UNKNOWN') THEN
        CASE WHEN SUBSTR(USER_NAME, -LENGTH(PARTY_ID)-1) = '@' || PARTY_ID
          THEN SUBSTR(USER_NAME, 1, LENGTH(USER_NAME)-LENGTH(PARTY_ID)-1) ELSE USER_NAME END END,
      CASE WHEN OBJECT_STATUS = 'A' AND STATUS IN ('ACTIVE','IN_PROGRESS','UNKNOWN') THEN PURPOSE END);

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.PURPOSE IS
  'SETUP before password creation; RESET when generating a Code for an ACTIVE credential.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.REQUEST_ID IS
  'Request holding this code IN_PROGRESS/UNKNOWN or consuming it to USED.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.REMOTE_CLIENT_ID IS
  'DSP client bound to the Code reservation; no password or password hash is stored locally.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.MAX_ATTEMPTS IS
  'Maximum failed verification attempts; INVALID when exhausted.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.STATUS IS
  '787 PENDING/ACTIVE/USED/EXPIRED/INVALID, plus IN_PROGRESS/UNKNOWN for credential operation safety.';

COMMENT ON TABLE HTH_BEA.HTH_API_PASSWORD_CODE IS
  'One-time HTH API password setup code generated by a maker; usable only after the original user-maintenance flow is approved.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.ID IS
  'Surrogate UUID primary key.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.PARTY_ID IS
  'Corporate party (CDC number) owning the HTH user; known at maker time.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.USER_NAME IS
  'Username snapshot; the OBDX user may not exist until the paired user creation is approved.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.TRANSACTION_ID IS
  'OBDX transaction id of the user-maintenance request that activated the code (DIGX_AP_TRANSACTION.TXN_ID).';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.CODE_CIPHER IS
  'AES-256-GCM ciphertext (Base64) of the numeric setup code; reversible for masked reveal and verification.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.STATUS IS
  'PENDING generated, ACTIVE usable after approval, USED first-time setup done, EXPIRED past expiry, INVALID superseded or locked.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.ATTEMPT_COUNT IS
  'Failed first-time setup verification attempts for this code.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.EXPIRY_TIME IS
  'Approval time plus exactly 24 hours; written when the original flow is approved.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.USED_TIME IS
  'Timestamp of the successful first-time password setup.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.OBJECT_STATUS IS
  'A=active, I=inactive (soft delete).';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.CREATED_BY IS
  'Operator who generated the code (GENERATED_BY in the requirement audit list).';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.CREATION_DATE IS
  'Code generation time (GENERATED_TIME in the requirement audit list).';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.LAST_UPDATED_BY IS
  'Operator or system user of the last status change.';

COMMENT ON COLUMN HTH_BEA.HTH_API_PASSWORD_CODE.LAST_UPDATE_DATE IS
  'Timestamp of the last status change.';

-- ============================================================================
-- 02 / API catalogue and URI mapping
-- ============================================================================
MERGE INTO HTH_BEA.HTH_API_MASTER T USING (SELECT 'HTH_API_ACCOUNT_ACTIVITY' ID, 'ACCOUNT_ACTIVITY' API_CODE, 'Account Activity / Trans. Inquiry' API_NAME, 10 DISPLAY_ORDER FROM DUAL) S ON (T.API_CODE = S.API_CODE)
WHEN MATCHED THEN UPDATE SET T.API_NAME = S.API_NAME, T.DISPLAY_ORDER = S.DISPLAY_ORDER, T.OBJECT_STATUS = 'A', T.LAST_UPDATED_BY = 'system', T.LAST_UPDATE_DATE = SYSDATE, T.OBJECT_VERSION_NUMBER = T.OBJECT_VERSION_NUMBER + 1
WHEN NOT MATCHED THEN INSERT (ID, API_CODE, API_NAME, DISPLAY_ORDER, OBJECT_STATUS, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, OBJECT_VERSION_NUMBER) VALUES (S.ID, S.API_CODE, S.API_NAME, S.DISPLAY_ORDER, 'A', 'system', SYSDATE, 'system', SYSDATE, 1);

MERGE INTO HTH_BEA.HTH_API_MASTER T USING (SELECT 'HTH_API_BALANCE_INQUIRY' ID, 'BALANCE_INQUIRY' API_CODE, 'Account available Balance / Net Balance Inquiry' API_NAME, 20 DISPLAY_ORDER FROM DUAL) S ON (T.API_CODE = S.API_CODE)
WHEN MATCHED THEN UPDATE SET T.API_NAME = S.API_NAME, T.DISPLAY_ORDER = S.DISPLAY_ORDER, T.OBJECT_STATUS = 'A', T.LAST_UPDATED_BY = 'system', T.LAST_UPDATE_DATE = SYSDATE, T.OBJECT_VERSION_NUMBER = T.OBJECT_VERSION_NUMBER + 1
WHEN NOT MATCHED THEN INSERT (ID, API_CODE, API_NAME, DISPLAY_ORDER, OBJECT_STATUS, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, OBJECT_VERSION_NUMBER) VALUES (S.ID, S.API_CODE, S.API_NAME, S.DISPLAY_ORDER, 'A', 'system', SYSDATE, 'system', SYSDATE, 1);

MERGE INTO HTH_BEA.HTH_API_MASTER T USING (SELECT 'HTH_API_DOWNLOAD_REPORT' ID, 'DOWNLOAD_REPORT' API_CODE, 'Download Report' API_NAME, 30 DISPLAY_ORDER FROM DUAL) S ON (T.API_CODE = S.API_CODE)
WHEN MATCHED THEN UPDATE SET T.API_NAME = S.API_NAME, T.DISPLAY_ORDER = S.DISPLAY_ORDER, T.OBJECT_STATUS = 'A', T.LAST_UPDATED_BY = 'system', T.LAST_UPDATE_DATE = SYSDATE, T.OBJECT_VERSION_NUMBER = T.OBJECT_VERSION_NUMBER + 1
WHEN NOT MATCHED THEN INSERT (ID, API_CODE, API_NAME, DISPLAY_ORDER, OBJECT_STATUS, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, OBJECT_VERSION_NUMBER) VALUES (S.ID, S.API_CODE, S.API_NAME, S.DISPLAY_ORDER, 'A', 'system', SYSDATE, 'system', SYSDATE, 1);

