MERGE INTO DIGX_FW_CONFIG_ALL_O T
USING (SELECT 'TAB_CHANGE_TASK_CODES' PROP_ID, 'DayOneConfig' PREFERENCE_NAME, 'OBDX_BU' DETERMINANT_VALUE FROM DUAL) S
ON (T.PROP_ID = S.PROP_ID AND T.PREFERENCE_NAME = S.PREFERENCE_NAME AND T.DETERMINANT_VALUE = S.DETERMINANT_VALUE)
WHEN MATCHED THEN UPDATE SET T.PROP_VALUE =
    CASE
      WHEN T.PROP_VALUE IS NULL OR TRIM(T.PROP_VALUE) IS NULL THEN 'PP_N_HTH_CERT_UPL'
      ELSE T.PROP_VALUE
        || CASE WHEN INSTR(T.PROP_VALUE, 'PP_N_HTH_CERT_UPL') = 0 THEN ',PP_N_HTH_CERT_UPL' ELSE '' END
    END,
    T.LAST_UPDATED_BY = 'system',
    T.LAST_UPDATED_DATE = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROP_ID, PREFERENCE_NAME, PROP_VALUE, DETERMINANT_VALUE, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATED_DATE)
VALUES (S.PROP_ID, S.PREFERENCE_NAME, 'PP_N_HTH_CERT_UPL', S.DETERMINANT_VALUE, 'system', SYSDATE, 'system', SYSDATE);

MERGE INTO DIGX_FW_CONFIG_ALL_O T
USING (SELECT 'CRM_ALLOWED_TASK_CODES' PROP_ID, 'CRMConfiguration' PREFERENCE_NAME, 'N' DETERMINANT_VALUE FROM DUAL) S
ON (T.PROP_ID = S.PROP_ID AND T.PREFERENCE_NAME = S.PREFERENCE_NAME AND T.DETERMINANT_VALUE = S.DETERMINANT_VALUE)
WHEN MATCHED THEN UPDATE SET T.PROP_VALUE =
    CASE
      WHEN T.PROP_VALUE IS NULL OR TRIM(T.PROP_VALUE) IS NULL THEN 'PP_N_HTH_CERT_UPL'
      ELSE T.PROP_VALUE
        || CASE WHEN INSTR(T.PROP_VALUE, 'PP_N_HTH_CERT_UPL') = 0 THEN '~PP_N_HTH_CERT_UPL' ELSE '' END
    END,
    T.LAST_UPDATED_BY = 'system',
    T.LAST_UPDATED_DATE = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROP_ID, PREFERENCE_NAME, PROP_VALUE, DETERMINANT_VALUE, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATED_DATE)
VALUES (S.PROP_ID, S.PREFERENCE_NAME, 'PP_N_HTH_CERT_UPL', S.DETERMINANT_VALUE, 'system', SYSDATE, 'system', SYSDATE);

INSERT INTO DIGX_AU_MAPPING (
  ID, MAINTENANCE_ID, ENTITY_VALUE, TASK_ID, ENTITY_TYPE, DETERMINANT_VALUE,
  CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATED_DATE,
  OBJECT_STATUS, OBJECT_VERSION_NUMBER
)
SELECT TO_CHAR(MAX_ID.MAX_ID + ROW_NUMBER() OVER (
         ORDER BY CONFIG.MAINTENANCE_ID, CONFIG.DETERMINANT_VALUE
       )),
       CONFIG.MAINTENANCE_ID,
       'corporateuser',
       'PP_N_HTH_CERT_UPL',
       'ROLE',
       CONFIG.DETERMINANT_VALUE,
       'system',
       SYSDATE,
       'system',
       SYSDATE,
       NULL,
       1
  FROM (
    SELECT '794049' MAINTENANCE_ID, '01' DETERMINANT_VALUE FROM DUAL
    UNION ALL
    SELECT '39173' MAINTENANCE_ID, 'OBDX_BU' DETERMINANT_VALUE FROM DUAL
  ) CONFIG
 CROSS JOIN (
    SELECT NVL(MAX(CASE WHEN REGEXP_LIKE(ID, '^[0-9]+$') THEN TO_NUMBER(ID) ELSE 0 END), 0) MAX_ID
      FROM DIGX_AU_MAPPING
 ) MAX_ID;

INSERT INTO DIGX_AU_MAPPING_PARAM (MAP_ID, LEVEL_NO, AUTH_TYPE_ID)
SELECT ID, 1, 'SIGNEROTPITOKEN'
  FROM DIGX_AU_MAPPING
 WHERE TASK_ID = 'PP_N_HTH_CERT_UPL';

