 VALUES ('HTH_API_PWD_RESET_USER_EMAIL_zh-Hant','EMAIL','HTH_API_PWD_RESET_USER_EMAIL_zh-Hant','HTH_API_PASSWORD_RESET_SUCCESS',TO_CLOB('<p>Dear Valued Customer,</p><p> </p> <p>Thank you for choosing BEA. Please be informed that you have successfully set up your H2H API Password via H2H API Password Setup Code.</p><p> </p> <p>You may now access H2H API services using this password. Please keep your password secure and only share it with authorized personnel who require access.</p><p> </p> <p>For enquiries, please call our Merchant Services Hotline on (852) 2211 1056 during office hours.</p><p> </p> <p>=======================================================================</p><p> </p> <p>Yours faithfully,</p><p> </p> <p>The Bank of East Asia, Limited</p><p> </p> <p>If there are any discrepancies between the English and Chinese versions of this email, the English version shall apply and prevail.</p><p> </p>  <p>This is a system-generated email – please do not reply to this email or via any hyperlinks in the message.</p><p> </p> <p>=======================================================================</p><p> </p> <p>尊貴的客戶：</p><p> </p> <p>現特函通知，您已透過H2H API密碼設定碼成功設定東亞銀行H2H API密碼。您現可使用該密碼使用H2H API服務。請妥善保管您的密碼，並僅與獲授權使用有關服務的人員分享。</p><p> </p> <p>如有垂詢，請致電本行：(852) 2211 1321。</p><p> </p> <p>感謝使用本行服務。</p><p> </p> <p>=======================================================================</p><p> </p> <p>謹啓</p><p> </p> <p>東亞銀行有限公司</p><p> </p> <p>中英文本文義如有歧異，概以英文本為準。此乃電腦系統發出之電郵，請勿回覆此電郵和電郵內的超連結。</p>'),USER,SYSDATE,USER,SYSDATE,1,'A',TO_CLOB('BEA Corporate Online : H2H API Password Setup Success 東亞企業網上銀行：銀企直連密碼設定成功'),'CZ','OBDX_BU');

