>=======================================================================</p><p> </p> <p>謹啓</p><p> </p> <p>東亞銀行有限公司</p><p> </p> <p>中英文本文義如有歧異，概以英文本為準。此乃電腦系統發出之電郵，請勿回覆此電郵和電郵內的超連結。</p>'),USER,SYSDATE,USER,SYSDATE,1,'A',TO_CLOB('BEA Corporate Online : H2H API Password Setup Code Approved 東亞企業網上銀行：銀企直連密碼設定碼已獲批准'),'CZ','OBDX_BU');

