INSERT INTO DIGX_CZ_FW_CONFIG_ALL_O
 (PROP_ID,PREFERENCE_NAME,PROP_VALUE,DETERMINANT_VALUE,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATED_DATE)
 SELECT 'SMS_DISPATCHER_SKIP_COUNTRY_CODE_EVENTID_LIST','DayOneConfig','INWARD_REMITTANCE_ALERT_SUCCESS,TD_MODE1_NOTIFICATION,TD_MODE1_NOTIFICATION_SMS_EN,TD_MODE1_NOTIFICATION_SMS_TC,TD_MODE1_NOTIFICATION_SMS_SC','OBDX_BU',USER,SYSDATE,USER,SYSDATE FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM DIGX_CZ_FW_CONFIG_ALL_O WHERE PROP_ID='SMS_DISPATCHER_SKIP_COUNTRY_CODE_EVENTID_LIST' AND PREFERENCE_NAME='DayOneConfig' AND DETERMINANT_VALUE='OBDX_BU');

UPDATE DIGX_CZ_FW_CONFIG_ALL_O SET PROP_VALUE=NVL(PROP_VALUE,'INWARD_REMITTANCE_ALERT_SUCCESS,TD_MODE1_NOTIFICATION,TD_MODE1_NOTIFICATION_SMS_EN,TD_MODE1_NOTIFICATION_SMS_TC,TD_MODE1_NOTIFICATION_SMS_SC') || ',HTH_API_SERVICE_SUBMIT_SUCCESS',
 LAST_UPDATED_BY=USER,LAST_UPDATED_DATE=SYSDATE
 WHERE PROP_ID='SMS_DISPATCHER_SKIP_COUNTRY_CODE_EVENTID_LIST' AND PREFERENCE_NAME='DayOneConfig' AND DETERMINANT_VALUE='OBDX_BU'
 AND INSTR(',' || REPLACE(UPPER(PROP_VALUE),' ','') || ',', ',HTH_API_SERVICE_SUBMIT_SUCCESS,')=0;

UPDATE DIGX_CZ_FW_CONFIG_ALL_O SET PROP_VALUE=NVL(PROP_VALUE,'INWARD_REMITTANCE_ALERT_SUCCESS,TD_MODE1_NOTIFICATION,TD_MODE1_NOTIFICATION_SMS_EN,TD_MODE1_NOTIFICATION_SMS_TC,TD_MODE1_NOTIFICATION_SMS_SC') || ',HTH_API_SERVICE_DISABLE_SUCCESS',
 LAST_UPDATED_BY=USER,LAST_UPDATED_DATE=SYSDATE
 WHERE PROP_ID='SMS_DISPATCHER_SKIP_COUNTRY_CODE_EVENTID_LIST' AND PREFERENCE_NAME='DayOneConfig' AND DETERMINANT_VALUE='OBDX_BU'
 AND INSTR(',' || REPLACE(UPPER(PROP_VALUE),' ','') || ',', ',HTH_API_SERVICE_DISABLE_SUCCESS,')=0;

UPDATE DIGX_CZ_FW_CONFIG_ALL_O SET PROP_VALUE=NVL(PROP_VALUE,'INWARD_REMITTANCE_ALERT_SUCCESS,TD_MODE1_NOTIFICATION,TD_MODE1_NOTIFICATION_SMS_EN,TD_MODE1_NOTIFICATION_SMS_TC,TD_MODE1_NOTIFICATION_SMS_SC') || ',HTH_API_SERVICE_EDIT_SUCCESS',
 LAST_UPDATED_BY=USER,LAST_UPDATED_DATE=SYSDATE
 WHERE PROP_ID='SMS_DISPATCHER_SKIP_COUNTRY_CODE_EVENTID_LIST' AND PREFERENCE_NAME='DayOneConfig' AND DETERMINANT_VALUE='OBDX_BU'
