-- ============================================================================
-- 17 / Add HTH certificate high-risk task only
-- ============================================================================
UPDATE DIGX_CZ_FW_CONFIG_ALL_O
 SET PROP_VALUE=CASE WHEN TRIM(PROP_VALUE) IS NULL THEN 'PP_N_HTH_CERT_UPL'
 ELSE PROP_VALUE || ',PP_N_HTH_CERT_UPL' END,LAST_UPDATED_BY=USER,LAST_UPDATED_DATE=SYSDATE
 WHERE PROP_ID='SUSPICIOUS_HIGH_RISK_TASK_ID' AND PREFERENCE_NAME='DayOneConfig' AND DETERMINANT_VALUE='OBDX_BU'
 AND INSTR(',' || REPLACE(PROP_VALUE,' ','') || ',', ',PP_N_HTH_CERT_UPL,')=0;

