COMMIT;
-- Reconcile before starting applications. Refresh OBDX caches/restart through the normal release flow.
SELECT TABLE_NAME FROM ALL_TABLES WHERE OWNER='HTH_BEA' AND TABLE_NAME LIKE 'HTH_%' ORDER BY TABLE_NAME;
SELECT COD_EVENT_ID,TXT_DEST_TYP,LOCALE,COD_MSG_TMPL_ID,SUBSCRIBER_TYPE
 FROM DIGX_EP_EVT_REC_B WHERE COD_EVENT_ID LIKE 'HTH_%' ORDER BY COD_EVENT_ID,TXT_DEST_TYP,LOCALE;
SELECT ID,NAME FROM DIGX_CM_TASK WHERE ID LIKE '%HTH%' OR ID LIKE '%HAP%' OR ID LIKE '%HUA%' ORDER BY ID;
UNDEFINE HTH_CODE_KEY DSP_MGMT_CLIENT_ID DSP_MGMT_CLIENT_SECRET DSP_MGMT_URL
UNDEFINE HTH_RUNTIME_OWNER BM_MAKER_POLICY BM_APPROVER_POLICY
